// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock reports the current time. It is an injection point for tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock is the default Clock backed by the wall clock.
var SystemClock Clock = systemClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	maxBurst int           // largest n AllowN will accept
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be > 0")

// New returns a Limiter with a full bucket. rate is tokens replenished per
// second; burst is the bucket capacity. clock may be nil, in which case the
// system clock is used.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || math.IsNaN(rate) || math.IsInf(rate, 0) || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = SystemClock
	}
	return &Limiter{
		tokens:   float64(burst),
		last:     clock.Now(),
		rate:     rate,
		burst:    float64(burst),
		maxBurst: burst,
		clock:    clock,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if elapsed := now.Sub(l.last); elapsed > 0 {
		l.tokens = math.Min(l.burst, l.tokens+l.rate*elapsed.Seconds())
		l.last = now
	}
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It returns false if n exceeds the burst capacity or n <= 0.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 || n > l.maxBurst {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the current number of available tokens, rounded down.
func (l *Limiter) Tokens() int {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return int(l.tokens)
}
