func TestConcurrentAllow(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1000, 100, clk)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	const goroutines = 50
	const per = 10
	results := make(chan bool, goroutines*per)
	var wg syncWait
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < per; j++ {
				results <- l.Allow()
			}
		}()
	}
	wg.Wait()
	close(results)
	allowed := 0
	for ok := range results {
		if ok {
			allowed++
		}
	}
	if allowed > 100 {
		t.Fatalf("allowed %d tokens, want <= burst 100", allowed)
	}
}

